Definition is_leaf (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 5 "S10!1+5+3$i;R+0$c;R+1$k;R+0$ps;R+2$t;R+3!2+40$tags;R0!2+6!3+7!1+8+1!3'9+1':#6!2,;+1#5!2+6!3+7!1+80!3'90'<#6!2,;0#1!2+6!3+7!1+8+2!3'9+2!1'=#5#4!2,;+2#3!3+7!1+8+3!3'9+3#1#4!2,;+3#2").
Lemma wl_at : forall i c k ps t, is_leaf i c k ps t -> wl_chk i c k ps t = true.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00$i;R+0$c;R+1$k;R+0$ps;R+2$t;R+3$IL;R!5'>#5#4#3#2#1!:'?':'<'@'A#6#5#4#3#2#1").
Qed.
(* [comment removed for export] *)
Definition stepping (i : nat) (sst cc : Z) : Prop := KD i = KStep sst cc \/ (KD i = KText /\ sst = 0 /\ cc = 0).

(* [comment removed for export] *)
Lemma kstep_c_range : forall i sst cc, KD i = KStep sst cc -> 0 <= cc <= 1.
Proof.
  intros i sst cc H. unfold KD in H.
  destruct (nth_in_or_default i KTAB KBad) as [Hin|Hd]; [|rewrite Hd in H; discriminate].
  rewrite H in Hin.
  assert (X : forallb (fun k => match k with KStep _ c => (0 <=? c) && (c <=? 1) | _ => true end)%bool KTAB = true) by (vm_compute; reflexivity).
  rewrite forallb_forall in X. specialize (X _ Hin). cbv beta iota in X. apply andb_prop in X as [X1 X2]. apply Z.leb_le in X1, X2. lia.
Qed.
Lemma kpush_c_range : forall i u m cc, KD i = KPush u m cc -> cc = 0.
Proof.
  intros i u m cc H. unfold KD in H.
  destruct (nth_in_or_default i KTAB KBad) as [Hin|Hd]; [|rewrite Hd in H; discriminate].
  rewrite H in Hin.
  assert (X : forallb (fun k => match k with KPush _ _ c => c =? 0 | _ => true end) KTAB = true) by (vm_compute; reflexivity).
  rewrite forallb_forall in X. specialize (X _ Hin). cbv beta iota in X. apply Z.eqb_eq. exact X.
Qed.
Lemma tab_all : forall (f : nat -> bool) i, forallb f (seq 0 (length KTAB)) = true -> (i < length KTAB)%nat -> f i = true.
Proof.
  intros f i H Hi. rewrite forallb_forall in H. apply H. apply (proj2 (in_seq _ _ _)). lia.
Qed.
Lemma kd_lt : forall i, KD i <> KBad -> (i < length KTAB)%nat.
Proof.
  intros i H. destruct (Nat.lt_ge_cases i (length KTAB)) as [Hl|Hg]; [exact Hl|].
  exfalso. apply H. unfold KD. apply nth_overflow. exact Hg.
Qed.
Lemma nx_tab : forallb (fun i => match KD i with KStep _ _ | KText | KPush _ _ _ => Nat.leb 105 (CC.cp_nx (cutn i)) | _ => true end) (seq 0 (length KTAB)) = true.
Proof. vm_compute. reflexivity. Qed.
Lemma stepping_nx : forall i sst cc, stepping i sst cc -> (105 <= CC.cp_nx (cutn i))%nat.
Proof.
  intros i sst cc Hs.
  assert (HK : KD i <> KBad) by (destruct Hs as [H|(H & _)]; rewrite H; discriminate).
  pose proof (tab_all _ i nx_tab (kd_lt i HK)) as X. cbv beta in X.
  destruct Hs as [H|(H & _)]; rewrite H in X; apply Nat.leb_le; exact X.
Qed.
Lemma push_nx : forall i u m cc, KD i = KPush u m cc -> (105 <= CC.cp_nx (cutn i))%nat.
Proof.
  intros i u m cc H.
  pose proof (tab_all _ i nx_tab (kd_lt i ltac:(rewrite H; discriminate))) as X. cbv beta in X.
  rewrite H in X. apply Nat.leb_le. exact X.
Qed.
