Definition goto_stepP (i : nat) (sst cc : Z) (cells : list kentry) (j : nat) (s : CC.subst) : Prop :=
  let adm := admlist cells (BV i) in
  exists (dj : Z) cj sstj, (dj = 0 \/ dj = 1) /\ sub s 53 = (if dj =? 1 then JM1 else V 53) /\
        ck_c (KD j) = Some cj /\ ck_sst (KD j) = Some sstj /\ tag_ok i (sub s 60) = true /\ buf_ok i (sub s 55) (sub s 56) = true /\
        ((KD j = KText /\ ((i = 2%nat /\ sub s 62 = SBO0) \/ (i = 1%nat /\ sub s 62 = V 62))) \/ (KD j = KStep sstj cj /\ i <> 1%nat)) /\
        ((cj + dj - cc = 0 /\ sstj = sst /\ keep_ok (CPX i) 58 (sub s 58) sstj = true /\ keep_ok (CP2X i) 59 (sub s 59) sstj = true /\ i <> 1%nat)
         \/ (cj + dj - cc = 1 /\ hasb cells cc (BV i) = true /\
             allb adm (fun b =>
               match sdesc sst b with
               | SGo s' u1 u2 out => (s' =? sstj) && Nat.eqb (length out) (if (Nat.eqb i 1 && Nat.eqb j 1)%bool then 1%nat else 0%nat) &&
                                     upd_ok (BV i) (CPX i) 58 u1 b (sub s 58) sstj && upd_ok (BV i) (CP2X i) 59 u2 b (sub s 59) sstj
               | SU4 d => match hexclass b with
                          | Some q => b85 i && (sstj =? SS_SP1) && (d =? b - clsk q) && match lit cells (fe_hs (A4 q)) with Some true => true | _ => false end &&
                                      oeqb (CPX i) (V 58) && expr_eqb (sub s 58) (A4 q) && keep_ok (CP2X i) 59 (sub s 59) sstj
                          | None => false end
               | SU8 d => b85 i && match hexclass b with Some q => match reg8 cells q with Some r => negb (region_eqb r R4) | None => false end | None => false end
               | _ => false
               end)%bool = true)).
