Lemma rb_goto : forall i c k ps j s, wl_chk i c k ps (CC.TGoto j s) = true -> KD i <> KDead ->
  let cells := SR.ps_cells ps in let adm := admlist cells (BV i) in
  (1 <= j <= 13)%nat /\
 ((KD i = KEntry /\ sub s 53 = V 32 /\ hasr cells (V 41) (DSST j) (DSST j) = true /\ (1 <= j <= 13)%nat /\
     sub s 58 = V 44 /\ sub s 59 = V 45 /\ sub s 60 = V 47 /\ sub s 55 = V 35 /\ sub s 56 = V 36 /\ (j = 1%nat -> sub s 62 = ELit 0))
  \/ (exists sst cc, stepping i sst cc /\ goto_stepP i sst cc cells j s)
  \/ (exists m cc, KD i = KPush true m cc /\ j = 2%nat /\ sub s 53 = JM1 /\ hasb cells cc (BV i) = true /\ b85 i = true /\
