  pose proof (tab_all (fun j => match KD j with KText => Nat.eqb j 1 | _ => true end) i ltac:(vm_compute; reflexivity) (kd_lt i ltac:(rewrite H; discriminate))) as X.
  cbv beta in X. rewrite H in X. apply Nat.eqb_eq. exact X.
Qed.
