Lemma h8_val : forall E q b cp cp2, hexclass b = Some q -> PB.uv E (V 111) = b -> PB.uv E (V 58) mod 2 ^ 32 = cp mod 2 ^ 32 -> PB.uv E (V 59) mod 2 ^ 32 = cp2 mod 2 ^ 32 ->
  PB.uv E (pair_form (V 58) (hex_form q (V 59) (V 111))) = pair_cp cp (PSKW.hexv cp2 (b - clsk q)) /\
  PB.uv E (H8 q) = UVZ.sx32 (pair_cp cp (PSKW.hexv cp2 (b - clsk q))).
Proof.
  intros E q b cp cp2 Hq Hb H58 H59.
  pose proof (hex_form_val E q (V 59) (V 111) b Hq Hb) as HA. rewrite H59, hexv_mod in HA.
  pose proof (PSBT.atom_t1 E (V 58) (PB.uv E (V 58) mod 2 ^ 32) eq_refl) as HT.
  pose proof (PSBT.atom_pair E _ (hex_form q (V 59) (V 111)) (PB.uv E (V 58) mod 2 ^ 32) (PSKW.hexv cp2 (b - clsk q)) HT HA (hexv_range cp2 (b - clsk q))) as HP.
  rewrite H58, pair_cp_mod in HP.
  split; [exact HP|]. exact (PSBT.uv_ext04_pair E _ cp _ HP).
Qed.
Lemma h4_val : forall E q b cp, hexclass b = Some q -> PB.uv E (V 111) = b -> PB.uv E (V 58) mod 2 ^ 32 = cp mod 2 ^ 32 ->
  PB.uv E (A4 q) = UVZ.sx32 (PSKW.hexv cp (b - clsk q)) /\ PB.uv E (H4 q) = UVZ.sx32 (PSKW.hexv cp (b - clsk q)).
Proof.
  intros E q b cp Hq Hb H58.
  pose proof (hex_form_val E q (V 58) (V 111) b Hq Hb) as HA. rewrite H58, hexv_mod in HA.
  split; [exact HA|]. exact (PSBT.uv_ext04_sx E (hex_form q (V 58) (V 111)) _ HA).
Qed.
(* [comment removed for export] *)
Lemma reg8_r4 : forall E (M : mem) cells q b r, know_ok RSEGS E M cells -> hexclass b = Some q -> PB.uv E (V 111) = b -> reg8 cells q = Some r -> r = R4.
Proof.
  intros E M cells q b r HK Hq Hb HR.
  destruct (h8_val E q b (PB.uv E (V 58)) (PB.uv E (V 59)) Hq Hb eq_refl eq_refl) as [_ HH].
  pose proof (pair_cp_range (PB.uv E (V 58)) (PSKW.hexv (PB.uv E (V 59)) (b - clsk q))) as RR.
  pose proof (reg_of_sound E M cells (H8 q) _ r HK HH ltac:(lia) HR) as IR.
  pose proof (pair_not_surr (PB.uv E (V 58)) (PSKW.hexv (PB.uv E (V 59)) (b - clsk q))) as NS.
  destruct r; cbn [inreg] in IR; [| | | reflexivity | |].
  all: first [rewrite NS in IR; discriminate | destruct IR as [_ IR]; lia].
Qed.
