Fixpoint terms_eqb (a b : list (Z * expr)) : bool :=
  match a, b with
  | [], [] => true
  | (k1, e1) :: r1, (k2, e2) :: r2 => ((k1 =? k2) && expr_eqb e1 e2 && terms_eqb r1 r2)%bool
  | _, _ => false
  end.
