Definition bufleaf_chk (i : nat) (cells : list kentry) : bool :=
  match blk0 i, cellv cells 232 8, cellv cells 240 8 with
  | Some (pe, ce), Some se, Some pl => (hdisj cells FSTK pe ce && hdisj cells FPOBJ pe ce && has cells (KUnk (SA pe 0) ce) && oeqb (SIZX i) se && oeqb (PTRX i) pl && expr_eqb pl pe)%bool
  | _, _, _ => false
  end.
(* [comment removed for export] *)
Definition exitw_chk (i : nat) (cells : list kentry) (a0e : expr) : bool :=
  match KD i with
  | KEntry => (expr_eqb a0e (V 11) && hasr cells (SLTUE (V 11) (ADD (V 11) (V 32))) 0 0 &&
               match cellv cells 209 1 with Some (ELit s) => (0 <=? s) && (s <? 3) | _ => false end && oeqb (cellv cells 220 1) (V 47) && bufleaf_chk i cells)%bool
  | KStep sst cc => (bufleaf_chk i cells && tag_ok i (match cellv cells 220 1 with Some e => e | None => ELit (-1) end) &&
                    match cellv cells 148 4, cellv cells 152 4 with Some _, Some _ => true | _, _ => false end &&
                    (if exh_fact cells cc then expr_eqb a0e (curform cc) else (expr_eqb a0e (curform (cc + 1)) && (cc =? 0) && oeqb (CPX i) (V 58))))%bool
  | KPush false m cc => (bufleaf_chk i cells && tag_ok i (match cellv cells 220 1 with Some e => e | None => ELit (-1) end) && expr_eqb a0e (curform (cc + 1)))%bool
  | KSetEc code => match CAX.cell_at cells (EVar 13) 0 4 with Some (ELit code') => code' =? code | _ => false end
  | KEsv => has cells (KBlob (SA (V 11) 0) (V 32) 1)
  | _ => true
  end.
Definition retw_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TGoto _ _ => true
  | CC.TOther pc =>
      let cells := SR.ps_cells ps in let regs := CA.ps_reglist ps in
      if (pc =? PUSHB) || (pc =? APPEND) then
        match CH2.ret_of G.RETS i k with
        | Some j =>
            bufleaf_chk i cells &&
            match cellv cells 232 8 with
            | Some se =>
                match cellv cells 240 8 with
                | Some pe =>
                    match SIZX j with
                    | Some sj =>
                        match blk0 j with
                        | Some (EVar v, _) =>
                            oeqb (SIZX i) se && oeqb (PTRX i) pe && Nat.eqb v (CC.cp_nx (cutn j) - APC.NCS - 2) && Nat.leb (CC.cp_nx c) v &&
                            ((pc =? APPEND) || Nat.leb 112 v) &&
                            lin_eqb (lin_of sj) (lin_of (ADD se (if pc =? PUSHB then ELit 1 else nth 12 regs (ELit 0)))) &&
                            match TAGX j with Some t' => oeqb (TAGX i) t' | None => true end
                        | _ => false
                        end
                    | None => false
                    end
                | None => false
                end
            | None => false
            end
        | None => false
        end
      else if pc =? ESV then
        bufleaf_chk i cells && expr_eqb (nth 8 regs (ELit 0)) CUR0 &&
        match TAGX i with Some t' => match cellv cells 220 1 with Some t2 => expr_eqb t' t2 | None => false end | None => false end
      else if pc =? RETPC then exitw_chk i cells (nth 10 regs (ELit 0))
      else true
  end%bool.
Lemma retw_ok : CH2.leaves_all G.CPS G.TAGS retw_chk = true.
Proof. vm_compute. reflexivity. Qed.
Lemma rb_ret : forall i c k ps pc j, CH2.is_leaf G.CPS G.TAGS i c k ps (CC.TOther pc) -> pc = PUSHB \/ pc = APPEND -> CH2.ret_of G.RETS i k = Some j ->
  let cells := SR.ps_cells ps in let regs := CA.ps_reglist ps in
  bufleaf_chk i cells = true /\
  exists se pe sj (v : nat) cj, cellv cells 232 8 = Some se /\ cellv cells 240 8 = Some pe /\ SIZX j = Some sj /\ SIZX i = Some se /\ PTRX i = Some pe /\
    blk0 j = Some (EVar v, cj) /\ v = (CC.cp_nx (cutn j) - APC.NCS - 2)%nat /\ (CC.cp_nx c <= v)%nat /\ (pc = PUSHB -> (112 <= v)%nat) /\
    (forall E, PB.uv E sj = PB.uv E (ADD se (if pc =? PUSHB then ELit 1 else nth 12 regs (ELit 0)))) /\
    (forall t, TAGX j = Some t -> TAGX i = Some t).
Proof.
  intros i c k ps pc j IL Hpc HR cells regs.
  pose proof (CH2.leaves_all_sound _ _ _ retw_ok _ _ _ _ _ IL) as X. unfold retw_chk in X. cbv beta iota zeta in X.
  assert (P1 : ((pc =? PUSHB) || (pc =? APPEND))%bool = true) by (destruct Hpc as [-> | ->]; vm_compute; reflexivity).
  rewrite P1, HR in X.
  apply andb_prop in X as [XB X]. split; [exact XB|].
  destruct (cellv (SR.ps_cells ps) 232 8) as [se|] eqn:Hse; [|cbv iota in X; discriminate X].
  destruct (cellv (SR.ps_cells ps) 240 8) as [pe|] eqn:Hpe; [|cbv iota in X; discriminate X].
  destruct (SIZX j) as [sj|] eqn:Hsj; [|cbv iota in X; discriminate X].
  destruct (blk0 j) as [[ev cj]|] eqn:Hb; [|cbv iota in X; discriminate X].
  destruct ev; try (cbv iota in X; discriminate X).
  match type of Hb with _ = Some (EVar ?v, _) => exists se, pe, sj, v, cj end.
  cbv iota in X.
  apply andb_prop in X as [X XG]. apply andb_prop in X as [X XF]. apply andb_prop in X as [X XE]. apply andb_prop in X as [X XD].
  apply andb_prop in X as [X XC]. apply andb_prop in X as [XA XA2].
  split; [exact Hse|]. split; [exact Hpe|]. split; [first [reflexivity | exact Hsj]|]. split; [apply oeqb_some; exact XA|]. split; [apply oeqb_some; exact XA2|].
  split; [first [reflexivity | exact Hb]|]. split; [apply Nat.eqb_eq; exact XC|]. split; [apply Nat.leb_le; exact XD|].
  split; [intros ->; apply orb_prop in XE as [XE|XE]; [vm_compute in XE; discriminate XE | apply Nat.leb_le; exact XE]|].
  split; [intros E; apply lin_of_eqv; exact XF|].
  intros t Ht. rewrite Ht in XG. apply oeqb_some. exact XG.
Qed.
