(* [comment removed for export] *)
Lemma rb_push : forall i c k ps, wl_chk i c k ps (CC.TOther PUSHB) = true -> KD i <> KDead ->
  let cells := SR.ps_cells ps in let adm := admlist cells (BV i) in let a1 := nth 11 (CA.ps_reglist ps) (ELit 0) in
  exists j, CH2.ret_of G.RETS i k = Some j /\ someb adm = true /\
  ((exists cc, KD i = KStep SS_ESC cc /\ KD j = KStep SS_TEXT (cc + 1) /\ hasb cells cc (BV i) = true /\
      allb adm (fun b => match sdesc SS_ESC b with SGo s' UKeep UKeep [o] => (s' =? SS_TEXT) && expr_eqb a1 (ELit o) | _ => false end)%bool = true)
   \/ (exists cc, KD i = KStep SS_U4 cc /\ KD j = KPush false 1 cc /\ hasb cells cc (BV i) = true /\ b85 i = true /\
      allb adm (fun b => match sdesc SS_U4 b, hexclass b with
             | SU4 d, Some q => (d =? b - clsk q) && match lit cells (fe_hs (A4 q)) with Some false => true | _ => false end &&
                               oeqb (CPX i) (V 58) && oeqb (cellv cells 148 4) (A4 q) &&
                               match reg4 cells q with Some r => Nat.ltb 0 (klen r) && vshape_ok (H4 q) r 0 a1 | None => false end
             | _, _ => false end)%bool = true)
   \/ (exists cc, KD i = KStep SS_U8 cc /\ KD j = KPush true 1 cc /\ hasb cells cc (BV i) = true /\ b85 i = true /\
      allb adm (fun b => match sdesc SS_U8 b, hexclass b with
             | SU8 d, Some q => (d =? b - clsk q) && oeqb (CPX i) (V 58) && oeqb (CP2X i) (V 59) && oeqb (cellv cells 152 4) (hex_form q (V 59) (V 111)) &&
                               match reg8 cells q with Some R4 => vshape_ok (H8 q) R4 0 a1 | _ => false end
             | _, _ => false end)%bool = true)
   \/ (exists u8 m cc, KD i = KPush u8 m cc /\ KD j = KPush u8 (S m) cc /\ hasb cells cc (BV i) = true /\ b85 i = true /\
      allb adm (fun b => match hexclass b with
           | Some q => match (if u8 then reg8 cells q else reg4 cells q) with Some r => (if u8 then PSCW.region_eqb r R4 else true) && Nat.ltb m (klen r) && vshape_ok (if u8 then H8 q else H4 q) r m a1 | None => false end
           | None => false end)%bool = true)
   \/ (exists cc, KD i = KStep SS_U8 cc /\ hasb cells cc (BV i) = true /\ b85 i = true /\      (* [comment removed for export] *)
      allb adm (fun b => match hexclass b with Some q => match reg8 cells q with Some r => negb (PSCW.region_eqb r R4) | None => false end | None => false end) = true)).
Proof.
  intros i c k ps HW HD cells adm a1.
  unfold wl_chk in HW.
  assert (LE : leaf_eval KD i c k ps (CC.TOther PUSHB) = push_chk i (KD i) cells adm a1) by (unfold leaf_eval; destruct (KD i); first [reflexivity | exfalso; exact (HD eq_refl)]).
  rewrite LE in HW. clear LE.
  destruct (push_chk i (KD i) cells adm a1) as [why| |kd] eqn:HP; try discriminate HW.
  { exfalso. clear HW. unfold push_chk in HP. destruct (KD i); try discriminate HP;
      repeat (match type of HP with context [if ?b then _ else _] => destruct b end; try discriminate HP). }
  destruct (CH2.ret_of G.RETS i k) as [j|] eqn:HR; [|discriminate HW].
  apply ckind_eqb_eq in HW.
  exists j. split; [reflexivity|].
  unfold push_chk in HP.
  destruct (KD i) as [|sst cc| |u8 m cc|code| | |] eqn:HK; try discriminate HP.
  - destruct (negb (someb adm && hasb cells cc (BV i))) eqn:G0; [discriminate HP|].
    apply negb_false_iff, andb_prop in G0 as [G1 G2]. split; [exact G1|].
    destruct (sst =? SS_ESC) eqn:E1.
    + apply Z.eqb_eq in E1. subst sst.
      match type of HP with (if ?b then _ else _) = _ => destruct b eqn:A end; [|discriminate HP].
      injection HP as <-. left. exists cc. split; [reflexivity|]. split; [exact HW|]. split; [exact G2|]. first [exact A | reflexivity].
    + destruct (sst =? SS_U4) eqn:E2.
      * apply Z.eqb_eq in E2. subst sst.
        match type of HP with (if ?b then _ else _) = _ => destruct b eqn:A end; [|discriminate HP].
        apply andb_prop in A as [A1 A2]. injection HP as <-.
        right; left. exists cc. split; [reflexivity|]. split; [exact HW|]. split; [exact G2|]. split; [exact A1|]. first [exact A2 | reflexivity].
      * destruct (sst =? SS_U8) eqn:E3; [|discriminate HP]. apply Z.eqb_eq in E3. subst sst.
        match type of HP with (if ?b then _ else _) = _ => destruct b eqn:A end.
        -- apply andb_prop in A as [A1 A2]. injection HP as <-.
           right; right; right; right. exists cc. split; [reflexivity|]. split; [exact G2|]. split; [exact A1|]. first [exact A2 | reflexivity].
        -- match type of HP with (if ?b then _ else _) = _ => destruct b eqn:B end; [|discriminate HP].
           apply andb_prop in B as [B1 B2]. injection HP as <-.
           right; right; left. exists cc. split; [reflexivity|]. split; [exact HW|]. split; [exact G2|]. split; [exact B1|]. first [exact B2 | reflexivity].
  - destruct (negb (someb adm && hasb cells cc (BV i) && b85 i)) eqn:G0; [discriminate HP|].
    apply negb_false_iff, andb_prop in G0 as [G0 G3]. apply andb_prop in G0 as [G1 G2]. split; [exact G1|].
    match type of HP with (if ?b then _ else _) = _ => destruct b eqn:A end; [|discriminate HP].
    injection HP as <-.
    right; right; right; left. exists u8, m, cc. split; [reflexivity|]. split; [exact HW|]. split; [exact G2|]. split; [exact G3|]. first [exact A | reflexivity].
Qed.
