Lemma rb_app : forall i c k ps, wl_chk i c k ps (CC.TOther APPEND) = true -> KD i <> KDead ->
  let cells := SR.ps_cells ps in let adm := admlist cells (BV i) in let a1 := nth 11 (CA.ps_reglist ps) (ELit 0) in let a2 := nth 12 (CA.ps_reglist ps) (ELit 0) in
  exists j, CH2.ret_of G.RETS i k = Some j /\
  ((KD i = KText /\ a1 = RUNS /\ a2 = RUNL /\ someb adm = true /\ hasb cells 0 (BV i) = true /\
      ((allb adm (fun b => b =? 92) = true /\ KD j = KStep SS_ESC 1) \/ (allb adm (fun b => b =? 34) = true /\ KD j = KStep SS_TEXT 0)))
   \/ (KD i = KText /\ a1 = RUNS /\ a2 = RUNL1 /\ someb adm = true /\ hasb cells 0 (BV i) = true /\ exh_fact cells 1 = true /\ KD j = KStep SS_TEXT 1 /\
       allb adm (fun b => match sdesc SS_TEXT b with SGo s' UKeep UKeep [o] => (s' =? SS_TEXT) && (o =? b) | _ => false end)%bool = true)
   \/ (exists cc, KD i = KStep SS_TEXT cc /\ a2 = ELit 0 /\ exh_fact cells cc = true /\ KD j = KStep SS_TEXT cc)).
