Lemma sx32_small : forall z, 0 <= z < 2 ^ 31 -> UVZ.sx32 z = z.
Proof. intros z Hz. unfold UVZ.sx32. rewrite Z.mod_small by lia. destruct (Z.ltb_spec z (2 ^ 31)); lia. Qed.
Lemma div_small31 : forall x p, 0 <= x < 2 ^ 31 -> 0 <= p -> 0 <= x / 2 ^ p < 2 ^ 31.
Proof.
  intros x p Hx Hp. assert (H1 : 1 <= 2 ^ p) by (change 1 with (2 ^ 0); apply Z.pow_le_mono_r; lia).
  split; [apply Z.div_pos; lia | apply Z.div_lt_upper_bound; nia].
Qed.
Lemma srl6_val : forall E H x n, PB.uv E H = UVZ.sx32 x -> 0 <= x < 2 ^ 31 -> PB.uv E (srl6 n H) = x / 2 ^ (6 * Z.of_nat n).
Proof.
  intros E H x n UH Hx. induction n as [|n IH].
  - cbn [srl6]. rewrite UH, sx32_small by lia. change (6 * Z.of_nat 0) with 0. rewrite Z.pow_0_r, Z.div_1_r. reflexivity.
  - cbn [srl6]. rewrite (PSBT.uv_srlw_lit E _ 6) by lia. rewrite IH.
    assert (HP : 0 < 2 ^ (6 * Z.of_nat n)) by (apply Z.pow_pos_nonneg; lia).
    pose proof (div_small31 x (6 * Z.of_nat n) Hx ltac:(lia)) as D.
    rewrite (Z.mod_small (x / 2 ^ (6 * Z.of_nat n))) by lia.
    rewrite Z.div_div by lia. rewrite <- Z.pow_add_r by lia.
    replace (6 * Z.of_nat n + 6) with (6 * Z.of_nat (S n)) by lia.
    apply sx32_small. apply div_small31; lia.
Qed.
Lemma srl6_eq : forall E H x k, PB.uv E H = UVZ.sx32 x -> 0 <= x < 2 ^ 31 -> 0 <= k < 64 -> k mod 6 = 0 ->
  PB.uv E (srl6 (Z.to_nat (k / 6)) H) = PB.uv E (EAlu Instr.ALU_SRL H (ELit k)).
Proof.
  intros E H x k UH Hx Hk H6.
  rewrite (srl6_val E H x _ UH Hx), (PSBT.uv_srl_lit E H k) by lia. rewrite UH, sx32_small by lia.
  rewrite Z2Nat.id by (apply Z.div_pos; lia). f_equal. f_equal. pose proof (Z.div_mod k 6 ltac:(lia)). lia.
Qed.
Lemma v_masked_w : forall E H x k m j, PB.uv E H = UVZ.sx32 x -> 0 <= x < 2 ^ 31 -> 1 <= k < 32 -> k mod 6 = 0 -> 1 <= j <= 8 -> k + j <= 32 -> m = 256 - 2 ^ j ->
  PB.uv E (ve_lead H k m) = m + (x / 2 ^ k) mod 2 ^ j.
Proof.
  intros E H x k m j UH Hx Hk H6 Hj Hkj Hm.
  unfold ve_lead, ANDE, ADD. cbv beta.
  transitivity (PB.uv E (EAlu Instr.ALU_AND (EAlu Instr.ALU_ADD (EAlu Instr.ALU_AND (EAlu Instr.ALU_SRL H (ELit k)) (ELit (- m - 1))) (ELit m)) (ELit 255))).
  - rewrite !(PSBT.uv_and E), !(PSBT.uv_add E), !(PSBT.uv_and E). rewrite (srl6_eq E H x k UH Hx ltac:(lia) H6). reflexivity.
  - apply (PSBT.v_masked E H x UH ltac:(lia) k m j); lia.
Qed.
Lemma v_cont_w : forall E H x k, PB.uv E H = UVZ.sx32 x -> 0 <= x < 2 ^ 31 -> 1 <= k <= 26 -> k mod 6 = 0 ->
  PB.uv E (ve_cont H k) = 128 + (x / 2 ^ k) mod 64.
Proof.
  intros E H x k UH Hx Hk H6.
  pose proof (div_small31 x k Hx ltac:(lia)) as D.
  assert (V : PB.uv E (srl6 (Z.to_nat (k / 6)) H) = UVZ.sx32 (x / 2 ^ k)).
  { rewrite (srl6_val E H x _ UH Hx). rewrite Z2Nat.id by (apply Z.div_pos; lia).
    replace (6 * (k / 6)) with k by (pose proof (Z.div_mod k 6 ltac:(lia)); lia).
    symmetry. apply sx32_small. exact D. }
  unfold ve_cont. exact (PSBT.v_cont0 E _ (x / 2 ^ k) V ltac:(lia)).
Qed.
Lemma vexp_sound : forall E H x r (idx : nat) e, PB.uv E H = UVZ.sx32 x -> 0 <= x < 2 ^ 32 -> inreg x r -> vexp H r idx = Some e -> PB.uv E e = nth idx (utf8_of x) 0 /\ (idx < length (utf8_of x))%nat.
Proof.
  intros E H x r idx e UH Hx IR HV.
  destruct r; cbn [inreg] in IR;
    [destruct IR as [IS IR] .. | ];
    destruct idx as [|[|[|[|idx]]]]; cbn [vexp] in HV; try discriminate HV; injection HV as <-;
    unfold utf8_of; try rewrite IS; cbv iota;
    repeat match goal with
           | |- context [if ?a <? ?b then _ else _] => destruct (Z.ltb_spec a b); cbv iota; try (exfalso; lia)
           | |- context [if ?a <=? ?b then _ else _] => destruct (Z.leb_spec a b); cbv iota; try (exfalso; lia)
           end;
    cbn [nth length]; (split; [|lia]).
  all: try assert (B31 : 0 <= x < 2 ^ 31) by lia.
  all: try rewrite !shiftr_div by lia; try rewrite !land63.
  all: first
    [ rewrite (v_masked_w E H x 6 192 6 UH B31) by (first [reflexivity | lia]); f_equal; apply Z.mod_small; split; [apply Z.div_pos; lia | apply Z.div_lt_upper_bound; lia]
    | rewrite (v_masked_w E H x 12 224 5 UH B31) by (first [reflexivity | lia]); f_equal; apply Z.mod_small; split; [apply Z.div_pos; lia | apply Z.div_lt_upper_bound; lia]
    | rewrite (v_masked_w E H x 18 240 4 UH B31) by (first [reflexivity | lia]); f_equal; apply Z.mod_small; split; [apply Z.div_pos; lia | apply Z.div_lt_upper_bound; lia]
    | rewrite (v_cont_w E H x 6 UH B31) by (first [reflexivity | lia]); reflexivity
    | rewrite (v_cont_w E H x 12 UH B31) by (first [reflexivity | lia]); reflexivity
    | unfold ve_cont0; exact (PSBT.v_cont0 E H x UH Hx)
    | unfold ve_and255, ANDE; cbv beta; rewrite (PSBT.v_and255 E H x UH Hx); apply Z.mod_small; lia
    | rewrite (PSBT.uv_lit E); apply Z.mod_small; lia ].
Qed.
