Lemma rb_esv : forall i c k ps, wl_chk i c k ps (CC.TOther ESV) = true -> KD i <> KDead -> CH2.is_leaf G.CPS G.TAGS i c k ps (CC.TOther ESV) ->
  let cells := SR.ps_cells ps in let adm := admlist cells (BV i) in let regs := CA.ps_reglist ps in
  let a1 := nth 11 regs (ELit 0) in let a2 := nth 12 regs (ELit 0) in
  exists j, CH2.ret_of G.RETS i k = Some j /\ KD j = KEsv /\ someb adm = true /\ hasb cells 0 (BV i) = true /\ allb adm (fun b => b =? 34) = true /\
    bufleaf_chk i cells = true /\ nth 8 regs (ELit 0) = CUR0 /\ (exists etg, TAGX i = Some etg /\ cellv cells 220 1 = Some etg) /\
    ((KD i = KText /\ a1 = RUNS /\ a2 = RUNL /\ hasr cells (V 55) 0 0 = true) \/ (KD i = KStep SS_TEXT 0 /\ PTRX i = Some a1 /\ SIZX i = Some a2)).
Proof.
  intros i c k ps HW HD IL cells adm regs a1 a2.
  pose proof (CH2.leaves_all_sound _ _ _ retw_ok _ _ _ _ _ IL) as XR. unfold retw_chk in XR. cbv beta iota zeta in XR.
  assert (PE : ((ESV =? PUSHB) || (ESV =? APPEND))%bool = false) by (vm_compute; reflexivity).
  rewrite PE, Z.eqb_refl in XR.
  apply andb_prop in XR as [XR XT]. apply andb_prop in XR as [XB XC].
  apply expr_eqb_eq in XC.
  destruct (TAGX i) as [t1|] eqn:HT; [|cbv iota in XT; discriminate XT].
  destruct (cellv (SR.ps_cells ps) 220 1) as [t2|] eqn:HC; [|cbv iota in XT; discriminate XT].
  apply expr_eqb_eq in XT. subst t2.
  unfold wl_chk in HW.
  assert (LE : leaf_eval KD i c k ps (CC.TOther ESV) = esv_chk i (KD i) cells adm a1 a2) by (unfold leaf_eval; destruct (KD i); first [reflexivity | exfalso; exact (HD eq_refl)]).
  rewrite LE in HW. clear LE.
  destruct (esv_chk i (KD i) cells adm a1 a2) as [why| |kd] eqn:HP; try discriminate HW.
  { exfalso. clear HW. unfold esv_chk in HP. destruct (KD i); try discriminate HP;
      repeat (match type of HP with context [if ?b then _ else _] => destruct b end; try discriminate HP). }
  destruct (CH2.ret_of G.RETS i k) as [j|] eqn:HR; [|discriminate HW].
  apply ckind_eqb_eq in HW.
  exists j. split; [reflexivity|].
  unfold esv_chk in HP.
  destruct (KD i) as [|sst cc| |u8 m cc|code| | |] eqn:HK; try discriminate HP.
  - match type of HP with (if ?b then _ else _) = _ => destruct b eqn:A end; [|discriminate HP]. injection HP as <-.
    apply andb_prop in A as [A A7]. apply andb_prop in A as [A A6]. apply andb_prop in A as [A A5]. apply andb_prop in A as [A A4].
    apply andb_prop in A as [A A3]. apply andb_prop in A as [A1 A2].
    apply Z.eqb_eq in A1. apply Z.eqb_eq in A2. subst sst cc.
    split; [exact HW|]. split; [exact A3|]. split; [exact A4|]. split; [first [exact A5 | reflexivity]|]. split; [exact XB|]. split; [exact XC|].
    split; [exists t1; split; [first [reflexivity | exact HT] | exact HC]|].
    right. split; [reflexivity|]. split; apply oeqb_some; assumption.
  - match type of HP with (if ?b then _ else _) = _ => destruct b eqn:A end; [|discriminate HP]. injection HP as <-.
    apply andb_prop in A as [A A6]. apply andb_prop in A as [A A5]. apply andb_prop in A as [A A4]. apply andb_prop in A as [A A3].
    apply andb_prop in A as [A1 A2].
    split; [exact HW|]. split; [exact A1|]. split; [exact A2|]. split; [first [exact A3 | reflexivity]|]. split; [exact XB|]. split; [exact XC|].
    split; [exists t1; split; [first [reflexivity | exact HT] | exact HC]|].
    left. split; [reflexivity|]. split; [apply expr_eqb_eq; exact A4|]. split; [apply expr_eqb_eq; exact A5|]. first [exact A6 | reflexivity].
Qed.
