Lemma rb_exit : forall i c k ps, wl_chk i c k ps (CC.TOther RETPC) = true -> KD i <> KDead -> CH2.is_leaf G.CPS G.TAGS i c k ps (CC.TOther RETPC) ->
  let cells := SR.ps_cells ps in let adm := admlist cells (BV i) in let regs := CA.ps_reglist ps in let a0e := nth 10 regs (ELit 0) in
  let tg := match cellv cells 220 1 with Some e => e | None => ELit (-1) end in
  (KD i = KEntry /\ a0e = V 11 /\ hasr cells (SLTUE (V 11) (ADD (V 11) (V 32))) 0 0 = true /\
     (exists s, cellv cells 209 1 = Some (ELit s) /\ 0 <= s < 3 /\ hasr cells (V 41) s s = true) /\ cellv cells 220 1 = Some (V 47) /\ bufleaf_chk i cells = true)
  \/ (exists sst cc, KD i = KStep sst cc /\ exh_fact cells cc = true /\ cellv cells 209 1 = Some (ELit sst) /\
        keep_ok (CPX i) 58 (match cellv cells 148 4 with Some e => e | None => ELit (-1) end) sst = true /\
        keep_ok (CP2X i) 59 (match cellv cells 152 4 with Some e => e | None => ELit (-1) end) sst = true /\ tag_ok i tg = true /\ a0e = curform cc /\ bufleaf_chk i cells = true /\
        cellv cells 148 4 <> None /\ cellv cells 152 4 <> None)
  \/ (exists cc, KD i = KStep SS_U4 cc /\ lt_fact cells cc = true /\ cellv cells 209 1 = Some (ELit 0) /\ someb adm = true /\ hasb cells cc (BV i) = true /\ b85 i = true /\ cc = 0 /\ CPX i = Some (V 58) /\
        allb adm (fun b => match sdesc SS_U4 b, hexclass b with
                | SU4 d, Some q => (d =? b - clsk q) && match lit cells (fe_hs (A4 q)), lit cells (fe_surr (H4 q)) with Some false, Some true => true | _, _ => false end &&
                                  oeqb (cellv cells 148 4) (A4 q)
                | _, _ => false end)%bool = true /\ tag_ok i tg = true /\ a0e = curform (cc + 1) /\ bufleaf_chk i cells = true)
  \/ (exists m cc, KD i = KPush false m cc /\ cellv cells 209 1 = Some (ELit 0) /\ someb adm = true /\ hasb cells cc (BV i) = true /\ b85 i = true /\
        allb adm (fun b => match hexclass b with Some q => match reg4 cells q with Some r => Nat.eqb m (klen r) && oeqb (cellv cells 148 4) (A4 q) | None => false end | None => false end)%bool = true /\
        tag_ok i tg = true /\ a0e = curform (cc + 1) /\ bufleaf_chk i cells = true)
