Module PSC := ParseStringChk_u5.PSC.
Lemma kinds_tab : forallb (fun i => match KD i with
                                   | KEntry | KStep _ _ | KText | KPush _ _ _ => PSC.kind_eqb (PSC.kind_of i) PSC.KPre
                                   | KSetEc _ => PSC.kind_eqb (PSC.kind_of i) PSC.KSetEc
                                   | KEsv => PSC.kind_eqb (PSC.kind_of i) PSC.KEsv
                                   | _ => true end) (seq 0 (length KTAB)) = true.
