Lemma kstep_sst_range : forall i sst cc, KD i = KStep sst cc -> 0 <= sst <= 11.
Proof.
  intros i sst cc H. unfold KD in H.
  destruct (nth_in_or_default i KTAB KBad) as [Hin|Hd]; [|rewrite Hd in H; discriminate].
  rewrite H in Hin.
  assert (X : forallb (fun k => match k with KStep s _ => (0 <=? s) && (s <=? 11) | _ => true end)%bool KTAB = true) by (vm_compute; reflexivity).
  rewrite forallb_forall in X. specialize (X _ Hin). cbv beta iota in X. apply andb_prop in X as [X1 X2]. apply Z.leb_le in X1, X2. lia.
Qed.
